'use strict';
const $=(s,root=document)=>root.querySelector(s);
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const N=(v,d=2)=>v==null||!Number.isFinite(Number(v))?'—':Number(v).toLocaleString('en-IN',{maximumFractionDigits:d,minimumFractionDigits:d});
const P=v=>v==null?'—':`${v>0?'+':''}${N(v)}%`;
const D=v=>!v?'Not available':new Date(v.length===10?v+'T00:00:00Z':v).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});
const T=v=>!v?'Not checked':new Date(v).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
const money=v=>v==null?'—':'₹'+N(v,0);
const cls=v=>v==null?'muted':v>=0?'positive':'negative';
const state={funds:[],status:null,search:'',plan:'Direct',option:'Growth',sort:'aum',page:1,token:0,fund:null,perf:null,tab:'overview',range:'3Y',benchmark:'Nifty Smallcap 250 TRI',chartMode:'comparison',newsFilter:'All',newsSearch:'',importCode:0};
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',6000);}
const HOSTED=window.SMALLCAP_CONFIG?.mode==='github';
async function api(url,options={}){if(HOSTED)return window.SmallcapStatic.request(url,options);const r=await fetch(url,{...options,headers:{'X-Smallcap-Client':'local',...(options.body&&!(options.body instanceof FormData)?{'Content-Type':'application/json'}:{}),...options.headers}});if(!r.ok){let msg;try{msg=(await r.json()).detail;}catch{msg=r.statusText;}throw Error(typeof msg==='string'?msg:JSON.stringify(msg));}return r.json();}
const post=(url,body)=>api(url,{method:'POST',body:JSON.stringify(body)});
function metric(label,value,sub,featured=false){return `<div class="metric-card ${featured?'featured':''}"><div class="metric-label">${E(label)}</div><div class="metric-value mono">${value}</div><div class="metric-sub">${sub}</div></div>`;}
function empty(title,message,action=''){return `<div class="empty"><h3>${E(title)}</h3><p>${E(message)}</p>${action}</div>`;}
function sourceLink(url,label='Source'){return url?`<a href="${E(url)}" target="_blank" rel="noopener noreferrer">${E(label)} ↗</a>`:'';}
function mark(name){return name.split(' ').filter(x=>!['Small','Cap','Fund','India'].includes(x)).slice(0,2).map(x=>x[0]).join('').toUpperCase();}
function metricValue(m){return m?E(m.value):'<span class="muted">Not available</span>';}
function feeFor(s){const ms=s.metrics||{};return ms.ter||ms.ter_observed||ms.base_expense_ratio||ms.expense_ratio;}
function unmatchedExpenses(f){return f.available_expenses?.length?`<section class="panel"><h2>Reported plan expenses</h2><p class="small muted">The NAV feed has not identified this series’ plan. These figures apply to the named plans below.</p><div class="table-wrap"><table><thead><tr><th>Plan</th><th>Expense</th><th>Reporting date</th><th>Source</th></tr></thead><tbody>${f.available_expenses.map(r=>`<tr><td>${E(r.plan)}</td><td>${N(r.value)}% ${r.metric==='base_expense_ratio'?'BER':r.metric==='expense_ratio'?'reported':'TER'}</td><td>${D(r.as_of)}</td><td>${sourceLink(r.source)}</td></tr>`).join('')}</tbody></table></div></section>`:'';}
function busy(){const jobs=state.status?.running||{};return Object.keys(jobs).length?`<div class="busy-strip"><span class="spinner" aria-hidden="true"></span><span>${E(Object.values(jobs).map(x=>x.detail).join(' · '))}</span></div>`:'';}

function shell(){
  $('#app').innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="#/"><span class="brand-icon">S</span><span>Smallcap Ledger</span></a><nav class="nav" aria-label="Main navigation"><a href="#/" data-nav="funds"><span class="nav-icon">▦</span> Funds</a><a href="#/archive" data-nav="archive"><span class="nav-icon">▤</span> Data</a><a href="#/settings" data-nav="settings"><span class="nav-icon">◌</span> Updates</a></nav><div class="sidebar-bottom minimal-status"><span></span>${HOSTED?'Daily updates':'Local mode'}</div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb" id="breadcrumb">Small-cap funds</div><div class="top-actions"><button id="refresh-all" aria-label="Refresh" title="Refresh">↻</button></div></header><main class="main" id="main" tabindex="-1"></main></div></div>`;
  $('#refresh-all').addEventListener('click',async()=>{if(HOSTED){await pollStatus();await route();toast('Latest published data loaded.');return;}try{await post('/api/refresh',{kind:'all'});toast('Updates started.');await pollStatus();}catch(e){toast(e.message);}});
}
function selectedNav(path){document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===path;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
function bindFundRows(){document.querySelectorAll('[data-fund-href]').forEach(row=>{const go=()=>location.hash=row.dataset.fundHref;row.addEventListener('click',e=>{if(e.target.closest('a,button,input,select,summary'))return;go();});row.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&!e.target.closest('a,button,input,select,summary')){e.preventDefault();go();}});});}
async function loadFunds(){const r=await api('/api/funds');state.funds=r.funds;}
async function route(){
  const token=++state.token;const parts=(location.hash||'#/').split('/');const page=parts[1]||'';
  $('#main').setAttribute('aria-busy','true');$('#main').innerHTML='<div class="loading" role="status"><span class="spinner" aria-hidden="true"></span> Opening your archive…</div>';
  try{
    if(page==='fund'){
      selectedNav('funds');const code=Number(parts[2]);state.tab=parts[3]||'overview';
      if(!['overview','performance','portfolio','fees','news'].includes(state.tab))state.tab='overview';
      const f=await api('/api/funds/'+code);if(token!==state.token)return;const official=f.metrics.benchmark?.value||'';if(state.fund?.family!==f.family){const stated=/bse.*250.*small/i.test(official)?'BSE 250 SmallCap TRI':'Nifty Smallcap 250 TRI';state.benchmark=state.status?.benchmarks?.some(b=>b.name===stated&&b.points>1)?stated:'Nifty Smallcap 250 TRI';}state.fund=f;state.importCode=code;
      await renderFund(token);
    }else if(page==='archive'){selectedNav('archive');await loadFunds();if(token!==state.token)return;renderArchive();}
    else if(page==='settings'){selectedNav('settings');if(HOSTED)renderHostedSettings();else renderSettings();}
    else{selectedNav('funds');await loadFunds();if(token!==state.token)return;renderDashboard();}
  }catch(e){if(token===state.token)$('#main').innerHTML=empty('Could not open this view',e.message,'<button id="retry">Try again</button>');$('#retry')?.addEventListener('click',route);}finally{if(token===state.token){$('#main').setAttribute('aria-busy','false');requestAnimationFrame(()=>$('#main')?.focus({preventScroll:true}));}}
}

function currentFundView(){if(state.plan==='Direct'&&state.option==='Growth')return'direct-growth';if(state.plan==='Regular'&&state.option==='Growth')return'regular-growth';if(state.plan==='All'&&state.option==='Growth')return'all-growth';if(state.plan==='All'&&state.option==='IDCW')return'idcw';return'all';}
function applyFundView(view){if(view==='direct-growth'){state.plan='Direct';state.option='Growth';}else if(view==='regular-growth'){state.plan='Regular';state.option='Growth';}else if(view==='all-growth'){state.plan='All';state.option='Growth';}else if(view==='idcw'){state.plan='All';state.option='IDCW';}else{state.plan='All';state.option='All';}}
function renderDashboard(){
  $('#breadcrumb').textContent='Funds';document.title='Small-cap funds · Smallcap Ledger';
  const dates=state.funds.map(f=>f.nav?.date).filter(Boolean).sort();const last=dates.at(-1);
  $('#main').innerHTML=`<div class="page-heading minimal-heading"><div><h1>Small-cap funds</h1><p>Compare the essentials. Open a fund for performance, portfolio and source history.</p></div><span class="freshness">NAV · ${last?D(last):'pending'}</span></div><div id="busy-area">${busy()}</div><section class="panel no-pad fund-directory-panel minimal-directory"><div class="minimal-controls"><div class="directory-search-wrap"><span aria-hidden="true">⌕</span><input id="search-funds" type="search" placeholder="Search fund or AMC" aria-label="Search funds" value="${E(state.search)}"></div><select id="view-filter" aria-label="Fund view"><option value="direct-growth" ${currentFundView()==='direct-growth'?'selected':''}>Direct · Growth</option><option value="regular-growth" ${currentFundView()==='regular-growth'?'selected':''}>Regular · Growth</option><option value="all-growth" ${currentFundView()==='all-growth'?'selected':''}>All · Growth</option><option value="idcw" ${currentFundView()==='idcw'?'selected':''}>All · IDCW</option><option value="all" ${currentFundView()==='all'?'selected':''}>All series</option></select><select id="sort-funds" aria-label="Sort funds">${[['aum','AUM · high to low'],['3','3Y return · high to low'],['1','1Y return · high to low'],['ter','Expense · low to high'],['family','Fund name · A–Z']].map(([v,t])=>`<option value="${v}" ${state.sort===v?'selected':''}>${t}</option>`).join('')}</select><span id="result-count" class="small muted"></span></div><div id="fund-table"></div></section><p class="footer-note minimal-note">Figures keep their reporting dates and source history. Missing values are never estimated.</p>`;
  $('#search-funds').addEventListener('input',e=>{state.search=e.target.value;state.page=1;fundTable();});
  $('#view-filter').addEventListener('change',e=>{applyFundView(e.target.value);state.page=1;fundTable();});
  $('#sort-funds').addEventListener('change',e=>{state.sort=e.target.value;state.page=1;fundTable();});
  fundTable();
}
function fundTable(){
  let rows=state.funds.filter(f=>(f.name+' '+f.family+' '+f.amc).toLowerCase().includes(state.search.toLowerCase())&&(state.plan==='All'||f.plan===state.plan)&&(state.option==='All'||f.option===state.option));
  if(state.sort==='family')rows.sort((a,b)=>a.family.localeCompare(b.family)||a.plan.localeCompare(b.plan)||a.option.localeCompare(b.option));
  else rows.sort((a,b)=>{const v=f=>state.sort==='aum'?Number(f.metrics.aum?.value??-Infinity):state.sort==='ter'?Number(feeFor(f)?.value??Infinity):f.returns[state.sort]??-Infinity;return state.sort==='ter'?v(a)-v(b):v(b)-v(a);});
  const unique=new Set(rows.map(f=>f.family)).size;const pages=Math.max(1,Math.ceil(rows.length/25));state.page=Math.min(state.page,pages);const shown=rows.slice((state.page-1)*25,state.page*25);
  $('#result-count').textContent=unique+' funds · '+rows.length+' series';
  $('#fund-table').innerHTML=!rows.length?empty('No matching funds','Try a different search or fund view.'):`<div class="table-wrap directory-table-wrap"><table class="fund-table directory-table minimal-fund-table"><thead><tr><th>Fund</th><th class="right">NAV</th><th class="right">AUM · ₹ Cr</th><th class="right">Expense</th><th class="right">1Y</th><th class="right">3Y CAGR</th></tr></thead><tbody>${shown.map(f=>{const fee=feeFor(f);return `<tr class="fund-row-link" tabindex="0" role="link" data-fund-href="/fund/${f.code}"><td><div class="fund-name"><span class="fund-mark">${mark(f.family)}</span><div><a class="fund-title" href="#/fund/${f.code}">${E(f.family)}</a><div class="fund-detail">${E(f.plan)} · ${E(f.option_label||f.option)}</div></div></div></td><td data-label="NAV" class="right"><b>₹${N(f.nav?.value,4)}</b><div class="fund-detail">${f.nav?D(f.nav.date):'—'}</div></td><td data-label="AUM" class="right">${N(f.metrics.aum?.value,0)}<div class="fund-detail">${f.metrics.aum?D(f.metrics.aum.as_of):'—'}</div></td><td data-label="Expense" class="right">${fee?N(fee.value)+'%':'—'}<div class="fund-detail">${fee?D(fee.as_of):''}</div></td><td data-label="1Y" class="right ${cls(f.returns['1'])}">${P(f.returns['1'])}</td><td data-label="3Y CAGR" class="right ${cls(f.returns['3'])}">${P(f.returns['3'])}</td></tr>`;}).join('')}</tbody></table></div><div class="pagination minimal-pagination"><span>${(state.page-1)*25+1}–${Math.min(state.page*25,rows.length)} of ${rows.length}</span><div><button id="prev" ${state.page===1?'disabled':''}>←</button><span>${state.page} / ${pages}</span><button id="next" ${state.page===pages?'disabled':''}>→</button></div></div>`;
  $('#prev')?.addEventListener('click',()=>{state.page--;fundTable();});$('#next')?.addEventListener('click',()=>{state.page++;fundTable();});bindFundRows();
}
function rangeStart(){if(state.range==='All')return '';if(state.range==='Custom')return state.customStart||'';const latest=state.fund?.nav_coverage?.last||new Date().toISOString().slice(0,10);return window.SmallcapAnalytics.shift(latest,parseInt(state.range)*(state.range.endsWith('Y')?12:1));}
async function getPerformance(){const q=new URLSearchParams({benchmark:state.benchmark,monthly:String(state.monthly||10000)});const s=rangeStart();if(s)q.set('start',s);if(state.range==='Custom'&&state.customEnd)q.set('end',state.customEnd);return api(`/api/funds/${state.fund.code}/performance?${q}`);}
function fundHeader(){const f=state.fund;return `<section class="fund-hero minimal-fund-hero"><div class="fund-hero-main"><a class="fund-back" href="#/">← Funds</a><h1>${E(f.family)}</h1><p class="fund-subtitle">${E(f.amc)} · ${E(f.plan)} · ${E(f.option_label||f.option)}</p></div><div class="fund-plan-control"><select id="plan-picker" class="plan-picker" aria-label="Plan and option">${f.plans.map(p=>`<option value="${p.code}" ${p.code===f.code?'selected':''}>${E(p.plan)} · ${E(p.option_label||p.option)}</option>`).join('')}</select></div></section><nav class="tabs fund-tabs minimal-tabs" aria-label="Fund sections">${[['overview','Overview'],['performance','Performance'],['portfolio','Portfolio'],['fees','Fees'],['news','Documents']].map(([v,t])=>`<a class="${state.tab===v?'active':''}" ${state.tab===v?'aria-current="page"':''} href="#/fund/${f.code}/${v}">${t}</a>`).join('')}</nav><div id="busy-area">${busy()}</div><div id="fund-content"></div>`;}
async function renderFund(token){const f=state.fund;document.title=f.family+' · Smallcap Ledger';$('#breadcrumb').innerHTML=`<a href="#/">All funds</a> / ${E(f.family)}`;$('#main').innerHTML=fundHeader();$('#plan-picker').addEventListener('change',e=>location.hash=`/fund/${e.target.value}/${state.tab}`);const el=$('#fund-content');
  if(state.tab==='news'){const docs=await api(`/api/funds/${f.code}/documents`);if(token!==state.token)return;renderNews(docs);}
  else if(state.tab==='portfolio'){await renderPortfolio();}
  else if(state.tab==='fees'){renderFees();}
  else{el.innerHTML='<div class="loading">Loading performance history…</div>';const p=await getPerformance();if(token!==state.token)return;state.perf=p;if(state.tab==='overview')renderOverview();else renderPerformance();}
}
function renderOverview(){const f=state.fund,p=state.perf,m=f.metrics,fee=feeFor(f),last=p.latest_nav;const ret1=p.stats.returns['1Y'],ret3=p.stats.returns['3Y'];const latestPortfolio=f.portfolios?.[0];
  $('#fund-content').innerHTML=`<section class="panel summary-panel"><div class="summary-strip"><div><span>NAV</span><b>${last?'₹'+N(last[1],4):'—'}</b><small>${last?D(last[0]):''}</small></div><div><span>AUM</span><b>${m.aum?'₹'+N(m.aum.value,0)+' Cr':'—'}</b><small>${m.aum?D(m.aum.as_of):''}</small></div><div><span>Expense</span><b>${fee?N(fee.value)+'%':'—'}</b><small>${fee?D(fee.as_of):''}</small></div><div><span>1Y</span><b class="${cls(ret1?.value)}">${P(ret1?.value)}</b></div><div><span>3Y CAGR</span><b class="${cls(ret3?.value)}">${P(ret3?.value)}</b></div></div></section>${unmatchedExpenses(f)}${f.option!=='Growth'?`<div class="callout warning">${E(p.method)}</div>`:''}<div class="overview-grid minimal-overview"><section class="panel comparison-overview"><div class="panel-head"><div><h2>Fund vs benchmark</h2><p class="small muted">₹100 rebased · ${E(state.range)}</p></div><a class="secondary-link" href="#/fund/${f.code}/performance">Details →</a></div><div class="chart-legend"><span><i class="legend-line"></i>Fund</span><span><i class="legend-line benchmark"></i>${E(state.benchmark)}</span></div><div id="overview-comparison"></div><p class="footer-note">${benchmarkNote(f)}</p></section><aside class="panel glance-panel minimal-facts"><h2>Fund facts</h2><dl class="facts compact">${[['Fund managers',m.managers],['Benchmark',m.benchmark],['Risk',m.risk],['Minimum SIP',m.minimum_sip],['Launch',m.fund_launch]].map(([label,v])=>`<div class="fact"><dt>${label}</dt><dd>${metricValue(v)}</dd></div>`).join('')}<div class="fact"><dt>Portfolio</dt><dd>${latestPortfolio?D(latestPortfolio.as_of):'Not parsed'}</dd></div></dl></aside></div><details class="panel objective-panel minimal-details"><summary>Investment objective</summary><div class="text-block section-space">${m.objective?E(m.objective.value):'Not yet extracted from a readable fund document.'}</div>${m.objective?`<p class="footer-note">${sourceLink(m.objective.source)}</p>`:''}</details>`;
  if(p.can_total_return)drawChart($('#overview-comparison'),p.comparison,[{label:'Fund',color:'#205ade'},{label:state.benchmark,color:'#dd7940'}]);else $('#overview-comparison').innerHTML=empty('Comparison unavailable',p.method);
}
function benchmarkNote(f){const official=f.metrics.benchmark?.value;if(!official)return 'The stated benchmark is unverified. '+E(state.benchmark)+' is shown as a category comparator.';const canonical=x=>x.toLowerCase().replace(/total[ -]*return[ -]*index/g,'tri').replace(/\bindex\b/g,'').replace(/[^a-z0-9]/g,'');const matches=canonical(official)===canonical(state.benchmark);return 'Stated benchmark: '+E(official)+'. '+(matches?'The selected series is its total-return index.':E(state.benchmark)+' is a category comparator; the stated index history is unavailable.');}

function drawChart(container,points,series,options={}){
  if(!points||points.length<2){container.innerHTML=empty('Not enough data to draw this chart','At least two observations are needed. Newly downloaded or imported records will appear here.');return;}
  const W=900,H=330,L=65,R=20,TOP=22,B=40;const dates=points.map(p=>Date.parse(p[0]));const minX=dates[0],maxX=dates.at(-1);let vals=points.flatMap(p=>p.slice(1).filter(v=>v!=null));let lo=Math.min(...vals),hi=Math.max(...vals);const pad=(hi-lo)*.1||Math.abs(hi)*.05||1;lo-=pad;hi+=pad;
  const x=d=>L+(d-minX)/(maxX-minX)*(W-L-R),y=v=>H-B-(v-lo)/(hi-lo)*(H-TOP-B);
  let grid='';for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4,py=y(v);grid+=`<line class="chart-grid" x1="${L}" x2="${W-R}" y1="${py}" y2="${py}"/><text class="chart-label" x="${L-12}" y="${py+4}" text-anchor="end">${N(v,options.percent?1:Math.abs(v)>1000?0:1)}${options.percent?'%':''}</text>`;}
  for(let i=0;i<5;i++){const dx=minX+(maxX-minX)*i/4;grid+=`<text class="chart-label" x="${x(dx)}" y="${H-8}" text-anchor="${i===0?'start':i===4?'end':'middle'}">${E(new Date(dx).toLocaleDateString('en-IN',{month:'short',year:'2-digit',timeZone:'UTC'}))}</text>`;}
  // Render every stored observation; no interpolation or synthetic points are inserted.
  const paths=series.map((s,j)=>{let d='';let previous=null;points.forEach((p,i)=>{if(p[j+1]==null){previous=null;return;}const gap=previous!==null&&!options.sparse&&(dates[i]-previous)>8*86400000;d+=(previous===null||gap?'M':'L')+x(dates[i]).toFixed(2)+','+y(p[j+1]).toFixed(2);previous=dates[i];});return `<path d="${d}" fill="none" stroke="${s.color}" stroke-width="2.5" stroke-linejoin="round"/>`;}).join('');
  container.innerHTML=`<div class="chart" tabindex="0" role="img" aria-label="${E(series.map(s=>s.label).join(' versus '))} chart, ${D(points[0][0])} to ${D(points.at(-1)[0])}. Use left and right arrow keys for values."><div class="chart-tip"></div><svg viewBox="0 0 ${W} ${H}" aria-hidden="true">${grid}${paths}<line data-guide x1="0" x2="0" y1="${TOP}" y2="${H-B}" stroke="#9aaac1" stroke-dasharray="3 4" opacity="0"/><rect x="${L}" y="${TOP}" width="${W-L-R}" height="${H-TOP-B}" fill="transparent"/></svg></div>`;
  const chart=$('.chart',container),tip=$('.chart-tip',chart),guide=$('[data-guide]',chart);let idx=points.length-1;
  function show(i){idx=Math.max(0,Math.min(points.length-1,i));const p=points[idx];tip.style.display='block';tip.innerHTML=`<b>${D(p[0])}</b>${series.map((s,j)=>`<div>${E(s.label)}: <strong>${p[j+1]==null?'—':(options.currency?'₹':'')+N(p[j+1],2)+(options.percent?'%':'')}</strong></div>`).join('')}`;guide.setAttribute('x1',x(dates[idx]));guide.setAttribute('x2',x(dates[idx]));guide.setAttribute('opacity','1');}
  chart.addEventListener('pointermove',e=>{const rect=$('svg',chart).getBoundingClientRect();const value=minX+((e.clientX-rect.left)/rect.width*W-L)/(W-L-R)*(maxX-minX);let left=0,right=dates.length-1;while(left<right){const mid=Math.floor((left+right)/2);if(dates[mid]<value)left=mid+1;else right=mid;}if(left&&Math.abs(dates[left-1]-value)<Math.abs(dates[left]-value))left--;show(left);});
  chart.addEventListener('pointerleave',()=>{tip.style.display='none';guide.setAttribute('opacity','0');});chart.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();show(idx+(e.key==='ArrowLeft'?-1:1));}});
}

function renderPerformance(){const f=state.fund,p=state.perf;const available=[...new Set(['Nifty Smallcap 250 TRI',state.benchmark,...(state.status?.benchmarks||[]).map(x=>x.name)])];
  $('#fund-content').innerHTML=`<section class="panel performance-workbench minimal-performance"><div class="panel-head"><div><h2>Performance</h2><p class="small muted">Fund vs benchmark over the selected period.</p></div><a class="secondary-link" href="/api/export/nav/${f.code}">Export NAV ↓</a></div><div class="performance-toolbar"><div class="range-buttons">${['1Y','3Y','5Y','10Y','All'].map(r=>`<button data-range="${r}" aria-pressed="${state.range===r}" class="${state.range===r?'active':''}">${r}</button>`).join('')}</div><select id="chart-mode" aria-label="Chart measure">${[['comparison','Fund vs benchmark'],['nav','NAV'],['drawdown','Drawdown'],['rolling','Rolling 3Y CAGR']].map(([v,t])=>`<option value="${v}" ${state.chartMode===v?'selected':''}>${t}</option>`).join('')}</select></div><div id="chart-message"></div><div id="performance-legend" class="chart-legend"></div><div id="performance-chart"></div><div class="chart-foot"><span id="chart-interval"></span><span>${E(p.method)}</span></div><section class="summary-strip performance-summary"><div><span>Max drawdown</span><b class="negative">${P(p.range_stats.max_drawdown)}</b></div><div><span>Volatility</span><b>${p.range_stats.volatility==null?'—':N(p.range_stats.volatility)+'%'}</b></div><div><span>Matched dates</span><b>${N(p.comparison.length,0)}</b></div></section><details class="inline-details"><summary>Advanced options</summary><div class="advanced-controls section-space"><label>From<input id="range-start" type="date" value="${E(rangeStart())}"></label><label>To<input id="range-end" type="date" value="${E(state.range==='Custom'?state.customEnd||'':p.last_nav||'')}"></label><button id="apply-range">Apply</button><label>Benchmark<select id="benchmark-select">${available.map(x=>`<option ${state.benchmark===x?'selected':''}>${E(x)}</option>`).join('')}</select></label></div><p class="footer-note">Stated benchmark: ${f.metrics.benchmark?E(f.metrics.benchmark.value):'not yet verified from a fund document'}. Historical benchmark changes may not be mapped.</p></details></section><details class="panel minimal-details"><summary>Return table</summary><div class="table-wrap section-space"><table><thead><tr><th>Period</th><th class="right">Fund</th><th class="right">${E(state.benchmark)}</th><th class="right">Difference</th></tr></thead><tbody>${['1M','3M','6M','1Y','3Y','5Y','10Y','Since start'].map(k=>{const a=p.comparison_stats.fund[k],b=p.comparison_stats.benchmark[k],diff=a&&b?a.value-b.value:null;return `<tr><td>${k==='Since start'?'Since common start':k}${a?.annualized?' CAGR':''}</td><td class="right ${cls(a?.value)}">${P(a?.value)}</td><td class="right ${cls(b?.value)}">${P(b?.value)}</td><td class="right ${cls(diff)}">${diff==null?'—':N(diff)+' pp'}</td></tr>`;}).join('')}</tbody></table></div></details><details class="panel minimal-details"><summary>SIP backtest</summary><div class="sip-controls section-space"><label class="inline">Monthly ₹ <input id="sip-amount" type="number" min="100" max="100000000" step="100" value="${state.monthly||10000}"></label><button id="calculate-sip">Calculate</button></div>${p.sip?`<div class="summary-strip four section-space"><div><span>Invested</span><b>${money(p.sip.invested)}</b></div><div><span>Final value</span><b>${money(p.sip.value)}</b></div><div><span>Gain / loss</span><b class="${cls(p.sip.gain)}">${money(p.sip.gain)}</b></div><div><span>XIRR</span><b>${P(p.sip.xirr)}</b></div></div>`:'<p class="muted small section-space">SIP results unavailable for this history.</p>'}</details>${p.stats.gaps?.length?`<div class="callout warning">${p.stats.gaps.length} gaps longer than seven calendar days exist in the saved NAV history.</div>`:''}`;
  document.querySelectorAll('[data-range]').forEach(b=>b.addEventListener('click',()=>{state.range=b.dataset.range;refreshPerformance();}));
  $('#chart-mode').addEventListener('change',e=>{state.chartMode=e.target.value;performanceChart();});
  $('#benchmark-select').addEventListener('change',e=>{state.benchmark=e.target.value;refreshPerformance();});
  $('#apply-range').addEventListener('click',()=>{state.range='Custom';state.customStart=$('#range-start').value;state.customEnd=$('#range-end').value;refreshPerformance();});
  $('#calculate-sip').addEventListener('click',()=>{state.monthly=Number($('#sip-amount').value);refreshPerformance();});
  performanceChart();
}
async function refreshPerformance(){try{const token=state.token;$('#fund-content').style.opacity='.65';const p=await getPerformance();if(token!==state.token)return;state.perf=p;renderPerformance();}catch(e){toast(e.message);}finally{if($('#fund-content'))$('#fund-content').style.opacity='1';}}
function performanceChart(){const p=state.perf;let points=[],series=[{label:'Fund',color:'#205ade'}],opts={},msg='';
  if(state.chartMode==='nav'){points=p.nav;series=[{label:'NAV',color:'#205ade'}];opts.currency=true;if(state.fund.option!=='Growth')msg='This chart shows NAV per unit only. Distributions reduce IDCW NAV; it is not a total-return chart.';}
  else if(state.chartMode==='drawdown'){points=p.range_stats.drawdown;opts.percent=true;series=[{label:'Drawdown',color:'#b33b49'}];}
  else if(state.chartMode==='rolling'){points=p.stats.rolling.filter(x=>(!rangeStart()||x[0]>=rangeStart())&&(!state.customEnd||state.range!=='Custom'||x[0]<=state.customEnd));opts.percent=true;series=[{label:'Rolling 3Y CAGR',color:'#087d67'}];}
  else{points=p.comparison;series=[{label:'Fund · rebased 100',color:'#205ade'},{label:state.benchmark+' · rebased 100',color:'#dd7940'}];if(!p.can_total_return)msg='A total-return comparison requires complete IDCW distribution history. Use the NAV view, or import complete payout data.';else if(!points.length)msg='The selected benchmark has no matching TRI history. Import an official TRI CSV in Data & archive. Fund returns remain available in the overview.';}
  $('#chart-message').innerHTML=msg?`<div class="callout warning section-space">${E(msg)} <a href="#/archive">Data & archive →</a></div>`:'';
  $('#performance-legend').innerHTML=series.map(s=>`<span><i class="legend-line" style="background:${s.color}"></i>${E(s.label)}</span>`).join('');drawChart($('#performance-chart'),points,series,opts);$('#chart-interval').textContent=points.length?D(points[0][0])+' – '+D(points.at(-1)[0]):'';
}

async function renderPortfolio(){const f=state.fund;const el=$('#fund-content');if(!f.portfolios.length){el.innerHTML=`<section class="panel">${empty('No parsed portfolio yet','Official portfolio documents may still be available in Documents.',`<a class="secondary-link" href="#/fund/${f.code}/news">Open documents →</a>`)}</section>`;return;}
  el.innerHTML=`<section class="panel portfolio-panel minimal-portfolio"><div class="panel-head"><div><h2>Portfolio</h2><p class="small muted">Holdings are shared across plans of the same fund.</p></div><select id="snapshot-picker" aria-label="Portfolio snapshot">${f.portfolios.map(p=>`<option value="${p.id}">${D(p.as_of)} · ${p.complete?'complete':'partial'}</option>`).join('')}</select></div><div id="holdings-view"></div></section>`;$('#snapshot-picker').addEventListener('change',e=>loadHoldings(e.target.value));await loadHoldings(f.portfolios[0].id);
}
async function loadHoldings(id){try{const token=state.token;const p=await api('/api/portfolios/'+id);if(token!==state.token)return;const total=p.holdings.reduce((s,x)=>s+x.weight,0),sectors={};for(const h of p.holdings){const k=h.sector||'Sector not supplied';sectors[k]=(sectors[k]||0)+h.weight;}
  $('#holdings-view').innerHTML=`<div class="portfolio-meta"><span class="badge ${p.complete?'green':'amber'}">${p.complete?'Complete':'Partial'}</span><span>${D(p.as_of)}</span><span>${p.holdings.length} positions</span><span>${N(total)}% disclosed</span><span>${sourceLink(p.source)}</span></div><div class="table-wrap section-space"><table class="holdings-table"><thead><tr><th>Holding</th><th>Sector</th><th class="right">Weight</th></tr></thead><tbody>${p.holdings.map(h=>`<tr><td><b>${E(h.name)}</b><div class="fund-detail">${E(h.isin||'')}</div></td><td>${E(h.sector||h.asset_type)}</td><td class="right">${N(h.weight)}%</td></tr>`).join('')}</tbody></table></div><div class="portfolio-actions"><a class="secondary-link" href="/api/export/portfolio/${p.id}">Download CSV ↓</a></div><details class="inline-details"><summary>Sector allocation</summary><div class="table-wrap section-space"><table><tbody>${Object.entries(sectors).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<tr><td>${E(k)}</td><td class="right">${N(v)}%</td></tr>`).join('')}</tbody></table></div></details><details class="inline-details"><summary>Changes since previous snapshot</summary>${p.previous?`<div class="table-wrap section-space"><table><thead><tr><th>Holding</th><th>Change</th><th class="right">Δ weight</th></tr></thead><tbody>${p.changes.map(x=>`<tr><td>${E(x.name)}</td><td class="small">${E(x.type)}</td><td class="right ${cls(x.change)}">${N(x.change)} pp</td></tr>`).join('')||'<tr><td colspan="3">No disclosed weight changes.</td></tr>'}</tbody></table></div>`:'<p class="muted small section-space">A comparable earlier snapshot is needed.</p>'}</details>`;
  }catch(e){toast(e.message);}}
const metricNames={aum:'Fund AUM',ter:'Total expense ratio',ter_observed:'TER · observed on website',base_expense_ratio:'Base expense ratio',expense_ratio:'Expense ratio · source does not specify TER/BER',base_ter:'Base TER (legacy reporting)',brokerage:'Brokerage cost',transaction_cost:'Transaction cost',statutory_levies:'Statutory levies',exit_load:'Exit load',benchmark:'Stated benchmark',managers:'Fund managers',fund_launch:'Fund launch',plan_launch:'Plan launch',objective:'Investment objective',risk:'Risk level',minimum_sip:'Minimum SIP',minimum_lumpsum:'Minimum lumpsum',stated_expense_maximum:'Stated maximum expense · scheme summary'};
function renderFees(){const f=state.fund,m=f.metrics;const hist=f.metric_history.filter(x=>x.plan==='All'||x.plan===f.plan);const fees=hist.filter(x=>['ter','ter_observed','base_expense_ratio','expense_ratio','brokerage','transaction_cost','statutory_levies','stated_expense_maximum'].includes(x.metric));const aum=hist.filter(x=>x.metric==='aum');const currentFee=feeFor(f);
  $('#fund-content').innerHTML=`${unmatchedExpenses(f)}<section class="panel summary-panel"><div class="summary-strip three"><div><span>Current AUM</span><b>${m.aum?'₹'+N(m.aum.value,0)+' Cr':'—'}</b><small>${m.aum?D(m.aum.as_of):''}</small></div><div><span>Expense</span><b>${currentFee?N(currentFee.value)+'%':'—'}</b><small>${currentFee?D(currentFee.as_of):''}</small></div><div><span>Exit load</span><b class="summary-text">${m.exit_load?E(m.exit_load.value):'—'}</b></div></div></section><div class="two-columns equal fees-chart-grid minimal-fees"><section class="panel"><div class="panel-head"><h2>AUM history</h2></div><div id="aum-chart"></div></section><section class="panel"><div class="panel-head"><h2>Expense history</h2></div><div id="fee-legend" class="chart-legend"></div><div id="fee-chart"></div></section></div><details class="panel minimal-details"><summary>Dated records</summary>${hist.length?`<div class="table-wrap section-space"><table><thead><tr><th>Metric</th><th>Date</th><th>Value</th><th>Source</th></tr></thead><tbody>${hist.map(r=>`<tr><td>${E(metricNames[r.metric]||r.metric)}<div class="fund-detail">${E(r.plan)}</div></td><td class="nowrap">${D(r.as_of)}</td><td>${E(r.value)}</td><td>${sourceLink(r.source)}</td></tr>`).join('')}</tbody></table></div><p><a href="/api/export/metrics/${f.code}" class="secondary-link">Export history ↓</a></p>`:empty('No dated records','No numeric history has been extracted yet.')}</details>`;
  function unique(rs){const map={};rs.forEach(r=>{if(!(r.as_of in map))map[r.as_of]=Number(r.value);});return Object.entries(map).sort((a,b)=>a[0].localeCompare(b[0]));}
  drawChart($('#aum-chart'),unique(aum),[{label:'AUM · ₹ Cr',color:'#205ade'}],{sparse:true});
  const feeSeries=[{key:'ter',label:'TER',color:'#087d67'},{key:'ter_observed',label:'Observed TER',color:'#205ade'},{key:'base_expense_ratio',label:'BER',color:'#a2670c'},{key:'expense_ratio',label:'Expense ratio',color:'#7353a6'}].filter(x=>fees.some(r=>r.metric===x.key));
  const feeMaps=feeSeries.map(s=>new Map(unique(fees.filter(x=>x.metric===s.key))));
  const feeDates=[...new Set(feeMaps.flatMap(m=>[...m.keys()]))].sort();
  $('#fee-legend').innerHTML=feeSeries.map(s=>`<span><i class="legend-line" style="background:${s.color}"></i>${E(s.label)}</span>`).join('');
  drawChart($('#fee-chart'),feeDates.map(d=>[d,...feeMaps.map(m=>m.get(d)??null)]),feeSeries,{percent:true,sparse:true});
}
function renderNews(docs){docs=docs.filter(d=>d.kind!=='news');const f=state.fund;$('#fund-content').innerHTML=`<section class="panel communications-panel minimal-documents"><div class="panel-head"><div><h2>Documents</h2><p class="small muted">Official publications from ${E(f.amc)}.</p></div><span class="small muted" id="document-count"></span></div><div class="document-toolbar minimal-document-toolbar"><input id="document-search" type="search" placeholder="Search documents" value="${E(state.newsSearch)}" aria-label="Search fund documents"><select id="document-filter" aria-label="Document type"><option>All</option><option>Factsheets</option><option>Portfolio</option><option>Market views</option><option>Disclosures</option><option>Source pages</option></select></div><div id="doc-list" class="doc-list"></div></section><p class="footer-note">${HOSTED?'Recent saved copies are available here; the complete version history remains in the full archive.':'Saved versions are retained from the time they are discovered.'}</p>`;
  const filters={'Factsheets':['factsheet'],'Portfolio':['portfolio'],'Market views':['market view'],'Disclosures':['disclosure','scheme document'],'Source pages':['source page']};$('#document-filter').value=state.newsFilter;
  const savedCount=d=>Number.isFinite(Number(d.saved_version_count))?Number(d.saved_version_count):(d.versions||[]).length;
  function list(){const q=state.newsSearch.trim().toLowerCase();const rows=docs.filter(d=>(state.newsFilter==='All'?d.kind!=='source page':filters[state.newsFilter]?.includes(d.kind))&&(!q||(d.title+' '+d.origin+' '+d.kind+' '+d.scope).toLowerCase().includes(q)));$('#document-count').textContent=rows.length+' item'+(rows.length===1?'':'s');$('#doc-list').innerHTML=rows.map(d=>{const versions=d.versions||[],saved=savedCount(d),latest=versions[0];const archiveLink=HOSTED&&saved>versions.length?projectLink('/releases/tag/tracker-history','Full archive'):'';const history=versions.length>1?`<details><summary>Versions</summary><div class="version-list">${versions.map(v=>`<a href="/api/archive/${v.hash}">${T(v.observed_at)} · ${N(v.bytes/1024,0)} KB</a>`).join('')}</div></details>`:'';return `<article class="doc-card minimal-doc-card"><div class="doc-body"><div class="doc-meta">${E(d.kind)} · ${d.published_at?D(d.published_at):'First found '+D(d.first_seen)}${d.scope==='AMC'?' · Fund house':''}</div><a class="doc-title" href="${E(d.url)}" target="_blank" rel="noopener noreferrer">${E(d.title)} ↗</a><div class="doc-actions">${sourceLink(d.url,'Original')}${latest?`<a href="/api/archive/${latest.hash}">Saved copy ↓</a>`:archiveLink}${history}</div></div></article>`;}).join('')||empty(q?'No matching documents':'No documents in this view',q?'Try another search or type.':'Official publications appear as they are discovered.');}
  $('#document-filter').addEventListener('change',e=>{state.newsFilter=e.target.value;list();});$('#document-search').addEventListener('input',e=>{state.newsSearch=e.target.value;list();});list();
}
function renderArchive(){if(HOSTED){renderHostedArchive();return;}document.title='Data & archive · Smallcap Ledger';$('#breadcrumb').textContent='Research / Data & archive';const c=state.status?.counts||{};
  $('#main').innerHTML=`<div class="page-heading"><div><div class="eyebrow">Your historical record</div><h1>Data & archive</h1><p>Inspect coverage, add dated records, and back up your saved history.</p></div><div class="page-actions"><a class="primary-link" href="/api/export/backup">Download data backup ↓</a></div></div><div id="busy-area">${busy()}</div><div class="metrics">${metric('NAV observations',N(c.nav_points||0,0),'Source and observation time retained',true)}${metric('TRI observations',N(c.benchmark_points||0,0),'Actual total-return index levels')}${metric('Portfolio snapshots',N(c.portfolios||0,0),'Dated, with completeness labels')}${metric('Source archive',N((c.archive_bytes||0)/1048576,1)+' MB','Files deduplicated by content')}</div><section class="panel"><div class="panel-head"><h2>Import a historical record</h2><span class="badge">CSV · UTF-8</span></div><p class="small muted">Use the original AMC or index-provider file as your source. The form states the expected units; blank data is never treated as zero.</p><form id="import-form" class="form-grid"><label>Record type<select name="kind" id="import-kind"><option value="metrics">AUM, fees and fund facts</option><option value="portfolio">Portfolio snapshot</option><option value="benchmark">Benchmark TRI history</option><option value="distributions">IDCW distribution history</option><option value="document">Original fund document</option></select></label><label id="import-scheme-label">Scheme<select name="code" id="import-code">${state.funds.map(f=>`<option value="${f.code}" ${f.code===state.importCode?'selected':''}>${E(f.family)} · ${E(f.plan)} · ${E(f.option)} (${f.code})</option>`).join('')}</select></label><label class="wide">Original source URL<input name="source" type="url" required placeholder="https://…"></label><div id="import-extra" class="wide"></div><label class="wide">File to import<input name="file" type="file" accept=".csv,text/csv" id="import-file" required></label><div class="wide form-hint" id="import-guide"></div><div class="wide flow-row"><button class="primary" type="submit">Import & retain history</button><a id="import-template" href="/api/templates/metrics">Download blank CSV template ↓</a></div><div id="import-result" class="wide import-result" role="status"></div></form></section><section class="panel"><h2>Benchmark coverage</h2>${(state.status?.benchmarks||[]).length?`<table><thead><tr><th>Total-return index</th><th>First date</th><th>Latest date</th><th class="right">Observations</th></tr></thead><tbody>${state.status.benchmarks.map(x=>`<tr><td>${E(x.name)}</td><td>${D(x.first)}</td><td>${D(x.last)}</td><td class="right">${N(x.points,0)}</td></tr>`).join('')}</tbody></table>`:empty('Benchmark download pending','Automatic collection uses NSE Indices’ public TRI history. BSE or other official TRI CSV files can be imported.')}<p class="footer-note">${sourceLink('https://www.niftyindices.com/reports/historical-data','NSE Indices historical downloads')} · Never import a price index under a TRI label.</p></section><section class="panel"><h2>Recent update activity</h2><div id="logs" class="logs">${logs()}</div></section>`;
  $('#import-kind').addEventListener('change',importGuide);$('#import-form').addEventListener('submit',async e=>{e.preventDefault();const btn=$('button[type=submit]',e.target);btn.disabled=true;$('#import-result').textContent='Validating and saving…';try{const r=await api('/api/import',{method:'POST',body:new FormData(e.target)});$('#import-result').textContent=r.note||`Saved ${r.rows} rows. Open the fund page to inspect the result.`;await pollStatus();}catch(err){$('#import-result').textContent=err.message;}finally{btn.disabled=false;}});importGuide();
}
function importGuide(){const k=$('#import-kind').value;$('#import-template').href='/api/templates/'+k;$('#import-scheme-label').style.display=k==='benchmark'?'none':'';let extra='',hint='';
  if(k==='metrics')hint='Columns: <code>metric,plan,as_of,value</code>. Dates: YYYY-MM-DD. AUM: <code>aum</code> in ₹ crore, plan <code>All</code>. Fees: <code>ter</code>, <code>base_expense_ratio</code>, <code>brokerage</code>, <code>transaction_cost</code>, <code>statutory_levies</code> in percentage points per year (0.65 means 0.65%), with plan Direct or Regular. Text fields: <code>exit_load</code>, <code>benchmark</code>, <code>managers</code>, <code>objective</code>, <code>fund_launch</code>, <code>risk</code>. Imported dates mean reported/effective dates.';
  if(k==='portfolio'){extra='<label>Portfolio reporting date<input type="date" name="as_of" required></label><label class="inline section-space"><input type="checkbox" name="complete" value="true">This is the full portfolio, including cash and other assets.</label>';hint='Columns: <code>isin,name,sector,weight,asset_type</code>. Weight is a percentage of fund net assets: 2.5 means 2.5%. Use asset types such as Equity, Cash, Debt or Derivative. ISIN and sector can be blank. Partial files are accepted and labelled; a full file should total approximately 100%.';}
  if(k==='benchmark'){extra='<label>Total-return index name<input name="benchmark" required value="Nifty Smallcap 250 TRI" list="benchmark-names"><datalist id="benchmark-names"><option>Nifty Smallcap 250 TRI</option><option>BSE 250 SmallCap TRI</option><option>Nifty Smallcap 100 TRI</option></datalist></label>';hint='Columns: <code>date,value</code>. Use YYYY-MM-DD dates and the official total-return index level. Do not use an ETF NAV, price index, cumulative percentage return, or net-return series as a TRI substitute.';}
  if(k==='distributions'){extra='<div class="form-grid"><label>Complete history from<input type="date" name="coverage_from" required></label><label>Complete history through<input type="date" name="coverage_to" required></label><label class="inline wide"><input name="complete" type="checkbox" value="true" required>I confirm every distribution in this interval is included, using the applicable reinvestment NAV.</label></div>';hint='Select the exact IDCW plan. Columns: <code>ex_date,amount,reinvestment_nav</code>. Amount is rupees per unit, before tax. Dates are YYYY-MM-DD. The app computes hypothetical reinvested total returns only inside the confirmed interval. This does not represent the cash balance of a payout investor.';}
  if(k==='document'){extra='<div class="form-grid"><label>Document title<input name="title" placeholder="Monthly factsheet"></label><label>Document type<select name="document_kind"><option value="factsheet">Factsheet</option><option value="portfolio">Portfolio</option><option value="disclosure">Disclosure / notice</option><option value="scheme document">Scheme summary / SID / KIM</option><option value="market view">Newsletter / market view</option></select></label><label>Applies to<select name="scope"><option value="Fund">This fund</option><option value="AMC">Whole fund house</option></select></label></div>';hint='Upload an original PDF, Excel, XML or CSV file. Its unchanged bytes and later versions are retained inside the selected fund’s Fund communications tab. Recognized factsheet and portfolio layouts are parsed; unsupported layouts remain downloadable.';}$('#import-file').accept=k==='document'?'.pdf,.xls,.xlsx,.xml,.csv':'.csv,text/csv';$('#import-template').style.display=k==='document'?'none':'';$('#import-extra').innerHTML=extra;$('#import-guide').innerHTML=hint;
}
function logs(){return (state.status?.jobs||[]).map(j=>`<div class="log"><div class="flow-row"><b>${E(j.kind)}</b><span class="badge ${j.status==='ok'?'green':j.status==='running'?'blue':'amber'}">${E(j.status)}</span><span class="muted">${T(j.started_at)}</span></div><details><summary>${E((j.detail||'Update in progress').split('\n')[0])}</summary><pre>${E(j.detail||'')}</pre></details></div>`).join('')||'<p class="muted">No updates yet.</p>';}
function projectLink(path,label){const repo=window.SMALLCAP_CONFIG?.repository;return repo?sourceLink('https://github.com/'+repo+path,label):'<span class="muted">'+E(label)+' · available after deployment</span>';}
function sourceStatusClass(status){return ['Gap','Partial','Limited','Pending','Excluded','Error','Failed'].includes(status)?'amber':'green';}
function sourceAttentionCount(){return (state.status?.sources||[]).filter(x=>sourceStatusClass(x.status)==='amber').length;}
function benchmarkCoverage(){return `<section class="panel"><h2>Benchmark coverage</h2><div class="table-wrap"><table><thead><tr><th>Total-return index</th><th>First date</th><th>Latest date</th><th class="right">Observations</th></tr></thead><tbody>${(state.status?.benchmarks||[]).map(x=>`<tr><td>${E(x.name)}</td><td>${D(x.first)}</td><td>${D(x.last)}</td><td class="right">${N(x.points,0)}</td></tr>`).join('')}</tbody></table></div><p class="footer-note">The comparison chart labels a category comparator when the fund’s stated index is unavailable. BSE TRI history and historical benchmark changes may remain gaps.</p></section>`;}
function renderHostedArchive(){const c=state.status?.counts||{};const funds=c.funds||new Set(state.funds.map(f=>f.family)).size;document.title='Data · Smallcap Ledger';$('#breadcrumb').textContent='Data';
  $('#main').innerHTML=`<div class="page-heading minimal-heading"><div><h1>Data</h1><p>Coverage and retained history.</p></div>${projectLink('/releases/tag/tracker-history','Download archive ↓')}</div><section class="panel summary-panel"><div class="summary-strip four"><div><span>NAV observations</span><b>${N(c.nav_points||0,0)}</b></div><div><span>AUM coverage</span><b>${N(c.aum_funds||0,0)} / ${N(funds,0)}</b></div><div><span>Expense coverage</span><b>${N(c.fee_funds||0,0)} / ${N(funds,0)}</b></div><div><span>Portfolios</span><b>${N(c.portfolios||0,0)}</b></div></div></section><div class="two-columns minimal-data-grid"><section class="panel"><h2>Archive</h2><p class="small muted">Complete cumulative history, source files and saved document versions.</p><dl class="facts compact"><div class="fact"><dt>Last build</dt><dd>${T(state.status?.server_time)}</dd></div><div class="fact"><dt>TRI observations</dt><dd>${N(c.benchmark_points||0,0)}</dd></div><div class="fact"><dt>Archive size</dt><dd>${N((c.archive_bytes||0)/1048576,1)} MB</dd></div></dl><p>${projectLink('/releases/tag/tracker-history','Download full archive')}</p></section>${benchmarkCoverage()}</div><details class="panel minimal-details"><summary>Recent update activity</summary><div id="logs" class="logs section-space">${logs()}</div></details>`;
}
function renderHostedSettings(){const sources=state.status?.sources||[];const attention=sourceAttentionCount();document.title='Updates · Smallcap Ledger';$('#breadcrumb').textContent='Updates';
  $('#main').innerHTML=`<div class="page-heading minimal-heading"><div><h1>Updates</h1><p>Daily collection and source health.</p></div>${projectLink('/actions/workflows/daily.yml','GitHub Actions ↗')}</div><div class="status-hero minimal-health ${attention?'warning':''}"><div class="status-hero-icon">${attention?'!':'✓'}</div><div><b>${attention?attention+' source'+(attention===1?'':'s')+' need attention':'Updates look healthy'}</b><p>Daily at 00:00 IST · latest build ${T(state.status?.server_time)}</p></div></div><section class="panel source-health-panel"><div class="panel-head"><div><h2>Sources</h2><p class="small muted">Latest visible check for each configured public source.</p></div><span class="small muted">${sources.length-attention} healthy · ${attention} attention</span></div><div class="table-wrap"><table class="source-status-table minimal-source-table"><thead><tr><th>Source</th><th>Checked</th><th>Status</th></tr></thead><tbody>${sources.map(x=>`<tr><td><b>${E(x.amc_match)}</b><div class="source-url">${sourceLink(x.url,x.label)}</div><div class="fund-detail">${E(x.detail||'Awaiting the next check')}</div></td><td class="small nowrap">${T(x.last_checked)}</td><td><span class="badge ${sourceStatusClass(x.status)}">${E(x.status)}</span></td></tr>`).join('')}</tbody></table></div></section><details class="panel minimal-details"><summary>Schedule & maintenance</summary><dl class="facts compact section-space"><div class="fact"><dt>Requested start</dt><dd>00:00 IST · daily</dd></div><div class="fact"><dt>GitHub cron</dt><dd>18:30 UTC</dd></div><div class="fact"><dt>Provider</dt><dd>GitHub Actions + Pages</dd></div></dl><p>${projectLink('/blob/main/GITHUB-SETUP.md','Maintenance guide')}</p></details>`;
}
function renderSettings(){const s=state.status?.settings||{};document.title='Update settings · Smallcap Ledger';$('#breadcrumb').textContent='Research / Update settings';$('#main').innerHTML=`<div class="page-heading"><div><div class="eyebrow">Local updates</div><h1>Keep the record growing.</h1><p>The app checks published data while its Windows command window is running.</p></div></div><div id="busy-area">${busy()}</div><section class="panel settings-card"><h2>Update schedule</h2><form id="settings-form" class="form-grid"><label class="inline wide"><input type="checkbox" name="auto_update" ${s.auto_update!==false?'checked':''}>Keep automatic updates enabled</label><label>NAV checks · minutes<input type="number" name="nav_interval_minutes" min="30" max="1440" value="${s.nav_interval_minutes||60}" required></label><label>Fund documents · hours<input type="number" name="disclosure_interval_hours" min="6" max="168" value="${s.disclosure_interval_hours||12}" required></label><div class="form-hint">Benchmark checks run every six hours. NAV backfill runs on the next daily update, including dates missed while the app was off.</div><div class="wide"><button type="submit" class="primary">Save schedule</button></div></form><p class="footer-note">Stopping the app or putting Windows to sleep pauses collection. Cached data remains available on the next launch. Website access failures retain previous records. This app does not trade or connect to investment accounts.</p></section><section class="panel"><div class="panel-head"><h2>Fund-house sources</h2><button id="check-docs">↻ Check documents</button></div><p class="small muted">Source pages are starting points for discovery. A successful page check does not mean every document or numeric field was extracted. Blocked, dynamic, missing and unparsed content remains a visible coverage gap.</p><div class="table-wrap"><table><thead><tr><th>Enabled</th><th>Fund house / source</th><th>Last check</th><th>Result</th></tr></thead><tbody>${(state.status?.sources||[]).map(x=>`<tr><td><input type="checkbox" data-source="${x.id}" aria-label="Enable ${E(x.label)} for ${E(x.amc_match)}" ${x.enabled?'checked':''}></td><td><b>${E(x.amc_match)}</b><div class="source-url">${sourceLink(x.url,x.label)}</div></td><td class="small nowrap">${T(x.last_checked)}</td><td><span class="badge ${x.status==='Gap'?'amber':''}">${E(x.status)}</span><div class="fund-detail" style="max-width:430px">${E(x.detail||'Awaiting the next check')}</div></td></tr>`).join('')}</tbody></table></div></section><section class="panel settings-card"><h2>Add a public fund-house page</h2><form id="source-form" class="form-grid"><label>Fund-house name contains<input name="amc_match" required placeholder="For example: HDFC"></label><label>Source label<input name="label" required placeholder="Monthly portfolios"></label><label class="wide">Public URL<input name="url" type="url" required placeholder="https://…"></label><div class="wide"><button type="submit">Add source</button></div></form></section><section class="panel settings-card"><h2>Where your records live</h2><p class="small">${E(state.status?.data_location||'The app’s data folder')}</p><p class="small muted">Backups contain the database and original archived files. Before restoring a backup, close the tracker and copy its data folder into this app’s folder.</p><a class="secondary-link" href="/api/export/backup">Download a data backup ↓</a></section>`;
  $('#settings-form').addEventListener('submit',async e=>{e.preventDefault();const d=new FormData(e.target);try{await post('/api/settings',{auto_update:d.has('auto_update'),nav_interval_minutes:Number(d.get('nav_interval_minutes')),disclosure_interval_hours:Number(d.get('disclosure_interval_hours'))});toast('Update schedule saved.');await pollStatus();}catch(err){toast(err.message);}});
  $('#source-form').addEventListener('submit',async e=>{e.preventDefault();try{await post('/api/sources',Object.fromEntries(new FormData(e.target)));await pollStatus();renderSettings();toast('Source added. It will be checked on the next document update.');}catch(err){toast(err.message);}});
  document.querySelectorAll('[data-source]').forEach(x=>x.addEventListener('change',async()=>{try{await post('/api/sources/'+x.dataset.source,{enabled:x.checked});toast('Source setting saved.');}catch(e){x.checked=!x.checked;toast(e.message);}}));
  $('#check-docs').addEventListener('click',async()=>{try{await post('/api/refresh',{kind:'documents'});toast('Document checks started.');}catch(e){toast(e.message);}});
}

async function pollStatus(){const previous=state.status;state.status=await api('/api/status');if($('#busy-area'))$('#busy-area').innerHTML=busy();if($('#logs'))$('#logs').innerHTML=logs();const before=previous?.running||{},after=state.status.running||{};const done=Object.keys(before).some(k=>!(k in after))||(HOSTED&&previous&&previous.server_time!==state.status.server_time);if(done){toast('An update finished. New records are now available.');if(!['archive','settings'].includes((location.hash||'').split('/')[1]))await route();}else if(state.funds.length===0&&state.status.counts.plans>0&&(location.hash==='#/'||!location.hash)){await loadFunds();renderDashboard();}}
shell();
(async()=>{try{await pollStatus();await route();}catch(e){$('#main').innerHTML=empty(HOSTED?'Saved data could not be loaded':'The local app is not responding',(HOSTED?'Refresh the page or check the latest deployment. ':'Keep START-WINDOWS.cmd running, then refresh this page. ')+e.message);}setInterval(()=>pollStatus().catch(()=>{if($('#busy-area'))$('#busy-area').innerHTML='<div class="callout warning">'+(HOSTED?'Could not check the latest published data. Refresh when your connection returns.':'Connection to the local app was lost. Reopen START-WINDOWS.cmd to resume updates.')+'</div>';}),HOSTED?300000:7000);})();
window.addEventListener('hashchange',route);

